class Solution {
    public List<String> fizzBuzz(int n) {
        List<String> answer = new ArrayList<>();
        for (int i = 1; i <= n; i++) {
            StringBuilder token = new StringBuilder();
            if (i % 3 == 0) {
                token.append("Fizz");
            }
            if (i % 5 == 0) {
                token.append("Buzz");
            }
            if (token.length() == 0) {
                token.append(i);
            }
            answer.add(token.toString());
        }
        return answer;
    }
}

import java.util.List;
import java.util.ArrayList;

class Solution {
    public List<String> fizzBuzz(int n) {
        int[] divisors = {3, 5};
        String[] words = {"Fizz", "Buzz"};
        List<String> answer = new ArrayList<>();
        for (int i = 1; i <= n; i++) {
            StringBuilder token = new StringBuilder();
            for (int rule = 0; rule < divisors.length; rule++) {
                if (i % divisors[rule] == 0) {
                    token.append(words[rule]);
                }
            }
            answer.add(token.length() == 0 ? String.valueOf(i) : token.toString());
        }
        return answer;
    }
}

import java.util.List;
