class Solution {
    public List<String> fizzBuzz(int n) {
        List<String> answer = new ArrayList<>();
        int nextFizz = 3;
        int nextBuzz = 5;
        for (int i = 1; i <= n; i++) {
            StringBuilder token = new StringBuilder();
            if (i == nextFizz) {
                token.append("Fizz");
                nextFizz += 3;
            }
            if (i == nextBuzz) {
                token.append("Buzz");
                nextBuzz += 5;
            }
            answer.add(token.length() == 0 ? String.valueOf(i) : token.toString());
        }
        return answer;
    }
}

import java.util.List;
import java.util.ArrayList;

class Solution {
    public List<String> fizzBuzz(int n) {
        String[] cycle = {
            "", "", "Fizz", "", "Buzz",
            "Fizz", "", "", "Fizz", "Buzz",
            "", "Fizz", "", "", "FizzBuzz"
        };
        List<String> answer = new ArrayList<>();
        for (int i = 1; i <= n; i++) {
            String token = cycle[(i - 1) % 15];
            answer.add(token.isEmpty() ? String.valueOf(i) : token);
        }
        return answer;
    }
}
